import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

enum HitResult {
    HIT, MISS, SUNK
}

class GameState {
    private final Set<String> remainingShips;
    private final Set<String> attacksMade;
    private final boolean gameOver;
    private final String winner;

    public GameState(
            Set<String> remainingShips,
            Set<String> attacksMade,
            boolean gameOver,
            String winner) {
        this.remainingShips = Collections.unmodifiableSet(
                new LinkedHashSet<>(remainingShips));
        this.attacksMade = Collections.unmodifiableSet(
                new LinkedHashSet<>(attacksMade));
        this.gameOver = gameOver;
        this.winner = winner;
    }

    public Set<String> getRemainingShips() {
        return remainingShips;
    }

    public Set<String> getAttacksMade() {
        return attacksMade;
    }

    public boolean isGameOver() {
        return gameOver;
    }

    public String getWinner() {
        return winner;
    }
}

class NavalBattleAdapter {
    private final Set<String> shipPositions;
    private final Set<String> attackPositions;
    private boolean gameOver;
    private String winner;

    public NavalBattleAdapter() {
        this.shipPositions = new LinkedHashSet<>();
        this.attackPositions = new LinkedHashSet<>();
        this.gameOver = false;
        this.winner = null;
    }

    public void placeShips(List<String> coordinates) {
        if (coordinates == null || coordinates.isEmpty()) {
            throw new IllegalArgumentException();
        }

        shipPositions.addAll(coordinates);
    }

    public HitResult receiveAttack(String coordinate) {
        if (coordinate == null || coordinate.isEmpty()) {
            throw new IllegalArgumentException();
        }

        attackPositions.add(coordinate);

        if (!shipPositions.contains(coordinate)) {
            return HitResult.MISS;
        }

        shipPositions.remove(coordinate);

        if (shipPositions.isEmpty()) {
            gameOver = true;
            winner = "Opponent";
