import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.atomic.AtomicInteger;

public class KeyValueStore {
    private final ConcurrentMap<String, Object> store = new ConcurrentHashMap<>();
    private final ConcurrentMap<String, AtomicInteger> accessCounts =
            new ConcurrentHashMap<>();
    private final ConcurrentMap<String, Long> lastAccessTimes =
            new ConcurrentHashMap<>();
    private final ConcurrentMap<Class<?>, AtomicInteger> typeCounts =
            new ConcurrentHashMap<>();

    public synchronized void put(String key, Object value) {
        validateKey(key);
        if (value == null) {
            throw new IllegalArgumentException("Value cannot be null");
        }

        Object previous = store.put(key, value);

        if (previous != null && previous.getClass() != value.getClass()) {
            decrementTypeCount(previous.getClass());
        }

        if (previous == null || previous.getClass() != value.getClass()) {
            typeCounts
                    .computeIfAbsent(value.getClass(), type -> new AtomicInteger())
                    .incrementAndGet();
        }
    }

    public synchronized void putAll(Map<String, ?> entries) {
        if (entries == null) {
            throw new IllegalArgumentException("Entries cannot be null");
        }

        for (Map.Entry<String, ?> entry : entries.entrySet()) {
            validateKey(entry.getKey());
            if (entry.getValue() == null) {
                throw new IllegalArgumentException("Values cannot be null");
            }
        }

        for (Map.Entry<String, ?> entry : entries.entrySet()) {
            put(entry.getKey(), entry.getValue());
        }
    }

    public Object get(String key) {
        validateKey(key);

        Object value = store.get(key);
        if (value != null) {
            accessCounts
                    .computeIfAbsent(key, ignored -> new AtomicInteger())
                    .incrementAndGet();
            lastAccessTimes.put(key, System.currentTimeMillis());
        }

        return value;
    }

    public int getAccessCount(String key) {
        validateKey(key);

        AtomicInteger count = accessCounts.get(key);
        return count == null ? 0 : count.get();
    }

    public long getLastAccessTime(String key) {
        validateKey(key);

        Long timestamp = lastAccessTimes.get(key);
        return timestamp == null ? 0L : timestamp;
    }

    public int getTypeCount(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }

        AtomicInteger count = typeCounts.get(type);
        return count == null ? 0 : count.get();
    }

    public Set<String> findKeysByType(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }

        Set<String> keys = new LinkedHashSet<>();
        for (Map.Entry<String, Object> entry : store.entrySet()) {
            if (entry.getValue().getClass().equals(type)) {
                keys.add(entry.getKey());
            }
        }

        return Collections.unmodifiableSet(keys);
    }

    public synchronized Statistics computeStatistics() {
        Map<Class<?>, Integer> typeDistribution = new LinkedHashMap<>();
        for (Map.Entry<Class<?>, AtomicInteger> entry : typeCounts.entrySet()) {
            int count = entry.getValue().get();
            if (count > 0) {
                typeDistribution.put(entry.getKey(), count);
            }
        }

        String keyWithMaxAccess = null;
        int maximumAccessCount = 0;

        for (String key : store.keySet()) {
            int count = getAccessCount(key);
            if (keyWithMaxAccess == null || count > maximumAccessCount) {
                keyWithMaxAccess = key;
                maximumAccessCount = count;
            }
        }

        long estimatedMemoryUsage = estimateMemoryUsage();

        return new Statistics(
                store.size(),
                keyWithMaxAccess,
                typeDistribution,
                estimatedMemoryUsage
        );
    }

    public synchronized void clear() {
        store.clear();
        accessCounts.clear();
        lastAccessTimes.clear();
        typeCounts.clear();
    }

    private synchronized long estimateMemoryUsage() {
        long memory = 0L;

        for (Map.Entry<String, Object> entry : store.entrySet()) {
            memory += estimateStringMemory(entry.getKey());
            memory += estimateValueMemory(entry.getValue());
        }

        return memory;
    }

    private long estimateValueMemory(Object value) {
        if (value instanceof String) {
            return estimateStringMemory((String) value);
        }

        String representation = String.valueOf(value);
        return 16L + estimateStringMemory(representation);
    }

    private long estimateStringMemory(String value) {
        return 16L + (long) value.length() * 2L;
    }

    private void decrementTypeCount(Class<?> type) {
        AtomicInteger count = typeCounts.get(type);
        if (count != null && count.decrementAndGet() <= 0) {
            typeCounts.remove(type, count);
        }
    }

    private void validateKey(String key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
    }

    public static final class Statistics {
        private final int totalEntries;
        private final String keyWithMaxAccess;
        private final Map<Class<?>, Integer> typeDistribution;
        private final long estimatedMemoryUsage;

        private Statistics(
                int totalEntries,
                String keyWithMaxAccess,
                Map<Class<?>, Integer> typeDistribution,
                long estimatedMemoryUsage
        ) {
            this.totalEntries = totalEntries;
            this.keyWithMaxAccess = keyWithMaxAccess;
            this.typeDistribution = Collections.unmodifiableMap(
                    new LinkedHashMap<>(typeDistribution)
            );
            this.estimatedMemoryUsage = estimatedMemoryUsage;
        }

        public int getTotalEntries() {
            return totalEntries;
        }

        public String getKeyWithMaxAccess() {
            return keyWithMaxAccess;
        }

        public Map<Class<?>, Integer> getTypeDistribution() {
            return typeDistribution;
        }

        public long getEstimatedMemoryUsage() {
            return estimatedMemoryUsage;
        }
    }
}

