import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.stream.Stream;

public class AdvancedFileProcessor {
    private final Path directoryPath;

    public AdvancedFileProcessor(String directoryPath) {
        if (directoryPath == null) {
            throw new IllegalArgumentException("Directory path cannot be null.");
        }

        Path path = Paths.get(directoryPath);
        if (!Files.isDirectory(path)) {
            throw new IllegalArgumentException("Provided path is not a directory: " + directoryPath);
        }

        this.directoryPath = path;
    }

    public Map<String, Object> processFiles() {
        int fileCount = 0;
        long totalSize = 0L;

        try (Stream<Path> paths = Files.walk(directoryPath)) {
            for (Path path : (Iterable<Path>) paths.filter(Files::isRegularFile)::iterator) {
                fileCount++;
                totalSize += Files.size(path);
            }
        } catch (IOException exception) {
            throw new UncheckedIOException("Failed to process files.", exception);
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("fileCount", fileCount);
        result.put("totalSize", totalSize);
        result.put("largestFile", "");
        result.put("wordFrequency", new HashMap<String, Integer>());

        return result;
    }
}

