import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

class AdvancedFileProcessor {
    private final Path directoryPath;

    public AdvancedFileProcessor(String directoryPath) {
        this.directoryPath = Paths.get(directoryPath);

        if (!Files.isDirectory(this.directoryPath)) {
            throw new IllegalArgumentException("Provided path is not a directory");
        }
    }

    private void processFileContent(
            Path file,
            Map<String, Integer> wordFrequency
    ) throws IOException {
        String content = Files.readString(file, StandardCharsets.UTF_8);
        String[] words = content.split("\\s+");

        for (String word : words) {
            String cleanedWord = word
                    .toLowerCase()
                    .replaceAll("[^a-z]", "");

            if (!cleanedWord.isEmpty()) {
                wordFrequency.merge(cleanedWord, 1, Integer::sum);
            }
        }
    }

    private Map<String, Integer> sortByValue(Map<String, Integer> map) {
        List<Map.Entry<String, Integer>> entries =
                new ArrayList<>(map.entrySet());

        entries.sort(
                Comparator
                        .comparing(Map.Entry<String, Integer>::getValue)
                        .reversed()
                        .thenComparing(Map.Entry::getKey)
        );

        Map<String, Integer> sortedMap = new LinkedHashMap<>();
        for (Map.Entry<String, Integer> entry : entries) {
            sortedMap.put(entry.getKey(), entry.getValue());
        }

        return sortedMap;
    }

    public Map<String, Object> processFiles() {
        Map<String, Object> result = new LinkedHashMap<>();
        Map<String, Integer> wordFrequency = new HashMap<>();

        int fileCount = 0;
        long totalSize = 0L;
        long largestFileSize = -1L;
        String largestFile = "N/A";

        try (DirectoryStream<Path> files = Files.newDirectoryStream(directoryPath)) {
            for (Path file : files) {
                if (!Files.isRegularFile(file)) {
                    continue;
                }

                fileCount++;

                long fileSize = Files.size(file);
                totalSize += fileSize;

                if (fileSize > largestFileSize) {
                    largestFileSize = fileSize;
                    largestFile = file.getFileName().toString();
                }

                processFileContent(file, wordFrequency);
            }
        } catch (IOException e) {
            // Files that cannot be read are skipped.
        }

        result.put("fileCount", fileCount);
        result.put("totalSize", totalSize);
        result.put("largestFile", largestFile);
        result.put("wordFrequency", sortByValue(wordFrequency));

        return result;
    }
}

