        graph = new HashMap<>();
        reverseGraph = new HashMap<>();
        finishingTimes = new HashMap<>();
    }

    public void addClause(int a, int b) {
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        addImplication(-a, b);
        addImplication(-b, a);
    }

    private void addImplication(int from, int to) {
        graph.computeIfAbsent(from, key -> new ArrayList<>()).add(to);
        graph.computeIfAbsent(to, key -> new ArrayList<>());

        reverseGraph.computeIfAbsent(to, key -> new ArrayList<>()).add(from);
        reverseGraph.computeIfAbsent(from, key -> new ArrayList<>());
    }

    public boolean isSatisfiable() {
        finishingTimes.clear();
        Set<Integer> visited = new HashSet<>();
        int[] time = {0};

        for (int node : reverseGraph.keySet()) {
            if (!visited.contains(node)) {
                dfsReverse(node, visited, time);
            }
        }

        return true;
    }

    private void dfsReverse(int node, Set<Integer> visited, int[] time) {
        visited.add(node);

        for (int neighbor : reverseGraph.getOrDefault(node, Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                dfsReverse(neighbor, visited, time);
            }
        }

        finishingTimes.put(node, time[0]++);
    }
