    private final Map<Integer, List<Integer>> graph;
    private final Map<Integer, List<Integer>> reverseGraph;
    private Map<Integer, Integer> finishingTimes;
    private Map<Integer, Integer> leaders;
    private Set<Integer> visited;
    private int time;

    public TwoSatSolver() {
        variables = new HashSet<>();
        graph = new HashMap<>();
        reverseGraph = new HashMap<>();
        finishingTimes = new HashMap<>();
        leaders = new HashMap<>();
    }

    public void addClause(int a, int b) {
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        addImplication(-a, b);
        addImplication(-b, a);
    }

    private void addImplication(int from, int to) {
        graph.computeIfAbsent(from, key -> new ArrayList<>()).add(to);
        graph.computeIfAbsent(to, key -> new ArrayList<>());

        reverseGraph.computeIfAbsent(to, key -> new ArrayList<>()).add(from);
        reverseGraph.computeIfAbsent(from, key -> new ArrayList<>());
    }

    public boolean isSatisfiable() {
        finishingTimes = new HashMap<>();
        leaders = new HashMap<>();
        visited = new HashSet<>();
        time = 0;

        Set<Integer> allNodes = new HashSet<>();
        allNodes.addAll(graph.keySet());
        allNodes.addAll(reverseGraph.keySet());

        for (List<Integer> neighbors : graph.values()) {
            allNodes.addAll(neighbors);
        }
        for (List<Integer> neighbors : reverseGraph.values()) {
            allNodes.addAll(neighbors);
        }

        // First pass: DFS on the reverse graph.
        for (int node : allNodes) {
            if (!visited.contains(node)) {
                dfsReverse(node);
            }
        }

        // Process nodes in decreasing order of finishing time.
        List<Integer> orderedNodes = new ArrayList<>(allNodes);
        orderedNodes.sort(
            (a, b) -> Integer.compare(finishingTimes.get(b), finishingTimes.get(a))
        );

        // Second pass: DFS on the original graph.
        visited.clear();

        for (int node : orderedNodes) {
            if (!visited.contains(node)) {
                dfsOriginal(node, node);
            }
        }

        // A 2-SAT instance is unsatisfiable if x and -x share a component.
        for (int variable : variables) {
            if (leaders.get(variable).equals(leaders.get(-variable))) {
                return false;
            }
        }

        return true;
    }

    private void dfsReverse(int node) {
        visited.add(node);

        for (int neighbor : reverseGraph.getOrDefault(node, Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
